INSERT INTO feature VALUES('stone-duality','theory','Finite Stone duality',NULL,'partial','notable',NULL,'The finite case of Stone duality as a library: the free distributive lattice on up to 64 generators in normal form, an antichain of terms each one machine word, with meet, join, order and substitution; finite Birkhoff duality both ways, a finite poset to the lattice of its down-sets and a lattice of sets to the poset of its join-irreducible members, each round trip the identity; and the monotone maps of cubes of up to six axes and of finite posets against the lattice homomorphisms the other way, one to one. A generator, an element or a vertex out of range is refused by name, and an enumeration past its budget is refused. The shapes crate decides its monotone band of face formulas in these normal forms, and its face spectrum and cube suites read the duality. Two lattices of sets glue along an open of each to their pullback over the shared localisation, whose spectrum is the pushout of the two spectra, with a restriction homomorphism to each side. A cover of an algebra is a unimodular sequence with its coefficients, replayed with no search over the ordered-algebras signature: on a lattice of sets a family whose join is the top, on a ring a sequence whose combination is one. The partition of unity glues the local sections that agree on each overlap, and over a commutative ring it splits a Čech cocycle; the projective line''s two charts are such a cover before its twist by minus two keeps one class in degree one.','theory-stone-duality theory-ordered-algebras','crates/theory-stone-duality/tests/free.rs crates/theory-stone-duality/tests/finite.rs crates/theory-stone-duality/tests/pushout.rs crates/theory-ordered-algebras/tests/cover.rs crates/theory-cellular-sheaves/tests/linear.rs crates/theory-shapes/tests/cubes.rs crates/theory-shapes/tests/spectrum.rs','crate-tests','#5267');
